EVALUATION_RESULTS: dict[str, dict] = {}

@router.get("/credit-evaluations/poll-result/{task_token}")
async def poll_credit_evaluation(
    task_token: str,
    current_user: User = Depends(get_current_user)
):
    if task_token not in EVALUATION_RESULTS:
        raise HTTPException(status_code=404, detail="Result not ready or expired")
    result = EVALUATION_RESULTS[task_token]
    if result.get("applicant_id") != current_user.id and not current_user.is_underwriter:
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized to view credit evaluation result")
    return EVALUATION_RESULTS.pop(task_token)
